<?php require_once __DIR__ . '/config/config.php';
require_once __DIR__ . '/app/helpers/helpers.php';
require_once __DIR__ . '/config/database.php';if(empty($_SESSION['google_register'])) redirect('/login.php'); $g=$_SESSION['google_register']; $error=''; if(is_post()){ $role=$_POST['role']??''; if(!in_array($role,['talent','company'],true)){ $error='Selecciona un rol válido'; } else { $stmt=db()->prepare('INSERT INTO users (name,email,password,role,avatar,google_auth,created_at) VALUES (:n,:e,:p,:r,:a,1,NOW())'); $stmt->execute(['n'=>$g['name'],'e'=>$g['email'],'p'=>password_hash(bin2hex(random_bytes(16)), PASSWORD_DEFAULT),'r'=>$role,'a'=>$g['avatar']]); $id=(int)db()->lastInsertId(); if($role==='talent'){ db()->prepare('INSERT INTO talent_profiles (user_id,headline,bio,skills,experience_years,location,xp) VALUES (?, ?, ?, ?, ?, ?, ?)')->execute([$id,'Talento registrado con Google','',trim($_POST['skills']??''),0,trim($_POST['location']??''),100]); } else { db()->prepare('INSERT INTO companies (user_id,name,description,location,verified,logo) VALUES (?, ?, ?, ?, 0, ?)')->execute([$id,trim($_POST['company_name']?:$g['name']),'',trim($_POST['location']??''),$g['avatar']]); } $_SESSION['user']=['id'=>$id,'name'=>$g['name'],'email'=>$g['email'],'role'=>$role,'avatar'=>$g['avatar']]; unset($_SESSION['google_register']); redirect('/dashboard.php'); } } ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="assets/css/styles.css"><title>Registro con Google</title></head><body class="auth-bg page-shell"><div id="loader"><div class="spinner-border text-primary"></div></div><div class="toast-container position-fixed bottom-0 end-0 p-3" style="z-index:1080"><div id="appToast" class="toast border-0 shadow"><div class="toast-body text-white bg-success rounded-4">Acción realizada correctamente</div></div></div><div class="position-fixed top-0 end-0 p-3"><button onclick="toggleTheme()" class="btn btn-soft"><i class="bi bi-moon-stars"></i></button></div><div class="container auth-shell"><div class="row justify-content-center align-items-center g-4 w-100"><div class="col-xl-4 d-none d-xl-block"><div class="auth-spotlight"><div class="kicker text-white mb-2">Google onboarding</div><h2 class="hero-title fs-2 text-white mb-3">Tu cuenta ya viene casi lista.</h2><p class="text-white-50">Completa tu registro, elige el rol correcto y después inicia sesión para entrar con la experiencia completa de OpenJobs.</p></div></div><div class="col-xl-5 col-lg-7 col-md-9"><div class="auth-card text-center"><img src="<?= e($g['avatar']) ?>" class="rounded-circle mb-3 shadow" width="92" height="92" alt="avatar"><h2 class="fw-bold mb-1"><?= e($g['name']) ?></h2><p class="section-subtitle mb-4"><?= e($g['email']) ?></p><?php if($error): ?><div class="alert alert-danger rounded-4 text-start"><?= e($error) ?></div><?php endif; ?><form method="post" class="row g-3 text-start mt-2"><div class="col-md-6"><label class="form-label">Rol</label><select class="form-select" name="role" id="role"><option value="">Selecciona</option><option value="talent">Talento</option><option value="company">Empresa</option></select></div><div class="col-md-6"><label class="form-label">Ubicación</label><input class="form-control" name="location"></div><div class="col-12 talent d-none"><label class="form-label">Habilidades</label><input class="form-control" name="skills" placeholder="Ej. React, SQL, UX"></div><div class="col-12 company d-none"><label class="form-label">Nombre empresa</label><input class="form-control" name="company_name"></div><div class="col-12 d-grid"><button class="btn btn-gradient">Crear cuenta</button></div></form></div></div></div></div><script>const role=document.getElementById('role');function t(){document.querySelector('.talent').classList.toggle('d-none', role.value!=='talent');document.querySelector('.company').classList.toggle('d-none', role.value!=='company');}role.addEventListener('change',t);</script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="assets/js/app.js"></script></body></html>